// ════════════════════════════════════════════════════════════════
//  HERALD (V233) — the knight's shield: Zak's arms of Luminar (the tree with its roots, the wheel, the crown of thorns
//  and the three drops, the crown and the cross) on a heater shield, navy and gold. Drawn from Zak's own artwork, taken
//  apart into colour masks (R: the charge, G: the border, R+G: the white of the cross, B 255: the drops, B 128: the black
//  edge; A: inside the shield) so the smith can paint it in any tinctures. Liveries no longer touch it.
//   HERALD.shield(parent) → handle {group, paint(col)} — col = {field, charge, rim, drops} ('#rrggbb'), missing = Luminar's
//   HERALD.TINCT — the tinctures the smith keeps · HERALD.DEF — Luminar's own colours · HERALD.preview(col, w) → dataURL
// ════════════════════════════════════════════════════════════════
const HERALD=(function(){
  const D={"png":"","aspect":0.8539505187549881,"poly":[[0.4994,0.9991],[0.5328,0.9894],[0.5651,0.981],[0.5969,0.9733],[0.6283,0.9654],[0.6601,0.9589],[0.6914,0.9505],[0.7238,0.9432],[0.7573,0.9361],[0.7922,0.9288],[0.8288,0.9212],[0.8685,0.914],[0.9098,0.905],[0.9554,0.8961],[0.9991,0.882],[0.9991,0.8397],[0.9988,0.8008],[0.999,0.7649],[0.9993,0.7314],[0.9994,0.6995],[0.9977,0.6686],[0.9962,0.6389],[0.9942,0.6102],[0.9918,0.5821],[0.9882,0.5546],[0.9834,0.5275],[0.9775,0.5008],[0.9705,0.4745],[0.9616,0.4488],[0.9516,0.4235],[0.9406,0.3985],[0.9277,0.3742],[0.9154,0.3494],[0.8996,0.3262],[0.8835,0.3029],[0.8662,0.2799],[0.8477,0.2571],[0.8272,0.2353],[0.806,0.2133],[0.7829,0.1922],[0.7583,0.1716],[0.7329,0.1501],[0.7054,0.1298],[0.6763,0.1094],[0.6452,0.0897],[0.6126,0.0685],[0.5776,0.0474],[0.54,0.0258],[0.4994,0.0015],[0.4588,0.0258],[0.4212,0.0474],[0.3862,0.0685],[0.3533,0.0889],[0.3224,0.1094],[0.2934,0.1298],[0.2663,0.1509],[0.2405,0.1716],[0.2159,0.1922],[0.1933,0.2139],[0.1716,0.2353],[0.1518,0.2577],[0.1333,0.2804],[0.1161,0.3034],[0.1,0.3266],[0.085,0.3502],[0.0711,0.3742],[0.059,0.3988],[0.0481,0.4237],[0.0381,0.449],[0.0292,0.4747],[0.0222,0.5009],[0.0163,0.5275],[0.0115,0.5546],[0.0079,0.5821],[0.0046,0.6102],[0.0026,0.6389],[0.0011,0.6686],[0.0003,0.6992],[0.0003,0.7311],[-0.0002,0.7649],[0.0,0.8008],[-0.0003,0.8397],[-0.0003,0.882],[0.042,0.8971],[0.0877,0.9061],[0.1297,0.9146],[0.1688,0.9224],[0.2055,0.9301],[0.24,0.9381],[0.2741,0.9447],[0.3066,0.952],[0.3384,0.9596],[0.3702,0.9662],[0.4017,0.9741],[0.4335,0.9818],[0.466,0.9894]]};
  const DEF={field:'#1b2a4e',charge:'#e2b33e',rim:'#e2b33e',drops:'#b0151d'};
  const TINCT=[['Azure','#1b2a4e'],['Sky','#3a6fb0'],['Gules','#8e1c1c'],['Vert','#1f5a32'],['Purpure','#4a2560'],['Sable','#1c1c22'],['Argent','#e8e6e0'],['Or','#e2b33e'],['Silver','#c4cad4'],['Copper','#b8743a']];
  let mask=null, wait=[]; const img=new Image();
  img.onload=()=>{ const c=document.createElement('canvas'); c.width=img.width; c.height=img.height; const x=c.getContext('2d'); x.drawImage(img,0,0); mask=x.getImageData(0,0,c.width,c.height); const w=wait; wait=[]; w.forEach(f=>f()); };
  img.src='data:image/png;base64,'+D.png;
  const hex=h=>{ const n=parseInt(String(h||'#000').slice(1),16); return [n>>16&255,n>>8&255,n&255]; };
  const keyOf=c=>JSON.stringify(Object.assign({},DEF,c||{}));
  function compose(cv,col){ col=Object.assign({},DEF,col||{}); cv.width=mask.width; cv.height=mask.height; const x=cv.getContext('2d'), o=x.createImageData(mask.width,mask.height), m=mask.data, d=o.data;
    const F=hex(col.field), C=hex(col.charge), Rm=hex(col.rim), Dr=hex(col.drops), K=[20,24,42], Wt=[244,240,230];
    for(let i=0;i<m.length;i+=4){ const r=m[i]/255, g=m[i+1]/255, b=m[i+2], a=m[i+3]; let p=F;
      const w=Math.min(r,g), e=r-w, rm=g-w, dk=b>90&&b<170?1:0, dr=b>=170?(b-170)/85:0;
      const mix=[0,1,2].map(k=>{ let v=F[k]*(1-w-e-rm)+Wt[k]*w+C[k]*e+Rm[k]*rm; v=v*(1-dr)+Dr[k]*dr; if(dk) v=v*0.15+K[k]*0.85; return v; });
      d[i]=mix[0]; d[i+1]=mix[1]; d[i+2]=mix[2]; d[i+3]=a; }
    x.putImageData(o,0,0); return cv; }
  const TEX={};
  function texFor(col,cb){ const k=keyOf(col); if(TEX[k]){ cb(TEX[k]); return; } const go=()=>{ if(!TEX[k]){ const t=new THREE.CanvasTexture(compose(document.createElement('canvas'),col)); t.anisotropy=4; TEX[k]=t; } cb(TEX[k]); }; if(mask) go(); else wait.push(go); }
  function preview(col,w){ if(!mask) return ''; const c=compose(document.createElement('canvas'),col), s=document.createElement('canvas'); s.width=w; s.height=Math.round(w*c.height/c.width); s.getContext('2d').drawImage(c,0,0,s.width,s.height); return s.toDataURL(); }
  /* the shield itself: a heater cut to the artwork's own outline, a little curved, its face the painted arms, its edge
     and back dark gilt metal with a leather strap */
  function shield(par,o){ o=o||{}; const Wd=o.w||0.56, Ht=Wd/D.aspect, y0=o.y0!==undefined?o.y0:-0.37, bend=g=>{ const p=g.attributes.position; for(let i=0;i<p.count;i++){ const x=p.getX(i); p.setZ(i,p.getZ(i)-x*x*0.7); } g.computeVertexNormals(); return g; };
    const sh=new THREE.Shape(); D.poly.forEach(([u,v],i)=>{ const x=(u-0.5)*Wd, y=y0+v*Ht; i?sh.lineTo(x,y):sh.moveTo(x,y); }); sh.closePath();
    const g=new THREE.Group(); g.userData.herald=true; par.add(g);
    const body=new THREE.Mesh(bend(new THREE.ExtrudeGeometry(sh,{depth:0.022,bevelEnabled:true,bevelSize:0.007,bevelThickness:0.007,bevelSegments:2,curveSegments:4}).translate(0,0,-0.02)),new THREE.MeshLambertMaterial({color:0x8a6a2a}));
    body.material.name='gold'; body.castShadow=true; body.userData.seg='shield'; body.userData.part='gold'; g.add(body);
    const fg=new THREE.ShapeGeometry(sh), p=fg.attributes.position, uv=new Float32Array(p.count*2); for(let i=0;i<p.count;i++){ uv[i*2]=p.getX(i)/Wd+0.5; uv[i*2+1]=(p.getY(i)-y0)/Ht; } fg.setAttribute('uv',new THREE.BufferAttribute(uv,2)); fg.translate(0,0,0.0105);
    const fm=new THREE.MeshLambertMaterial({color:0xffffff}), face=new THREE.Mesh(bend(fg),fm); face.userData.keepMat=true; face.userData.seg='shield'; face.userData.part='face'; face.castShadow=true; g.add(face);
    [[0.11,0.12],[-0.06,0.12]].forEach(([y,w])=>{ const s=new THREE.Mesh(new THREE.BoxGeometry(w,0.035,0.012),new THREE.MeshLambertMaterial({color:0x5a3a22})); s.position.set(0,y,-0.03); s.userData.seg='shield'; s.userData.part='leather'; g.add(s); });
    const H={group:g, key:null, paint(col){ const k=keyOf(col); if(k===H.key) return; H.key=k; texFor(col,t=>{ fm.map=t; fm.needsUpdate=true; }); } };
    H.paint(o.col); return H; }
  /* the smith at the Great Forge repaints it: choose the field, the charge (tree, wheel, crown), the border and the drops
     from his tinctures, see it as you go, and pay him when you like it */
  const PARTS=[['field','Field'],['charge','Arms (tree, wheel, crown)'],['rim','Border'],['drops','The three drops']], COST=30;
  function smithy(keeper,wares){ const S=GAME.S, cur=Object.assign({},DEF,S.shieldCol||{}); let pick=Object.assign({},cur), msg='';
    const draw=()=>{ let h=`<div style="display:flex;gap:14px;align-items:flex-start;flex-wrap:wrap"><img src="${preview(pick,150)}" alt="Your shield" style="width:150px;flex:none;filter:drop-shadow(0 3px 6px rgba(0,0,0,.5))"><div style="flex:1;min-width:200px">`;
      PARTS.forEach(([k,n])=>{ h+=`<div class="gm-hint" style="margin:6px 0 4px">${n}</div><div style="display:flex;flex-wrap:wrap;gap:5px">`+TINCT.map(([tn,c])=>`<button data-act="c:${k}:${c}" title="${tn}" aria-label="${n}: ${tn}" style="width:30px;height:30px;border-radius:6px;background:${c};border:${pick[k]===c?'3px solid #fff':'1px solid rgba(255,255,255,.35)'};cursor:pointer"></button>`).join('')+'</div>'; });
      h+='</div></div>'+(msg?`<p class="gm-hint">${msg}</p>`:'');
      const same=JSON.stringify(pick)===JSON.stringify(cur);
      h+=`<button class="gm-btn" data-act="paint" ${same?'disabled':''}>Paint it — ${COST} gold</button><button class="gm-item" data-act="luminar"><span>⚜ Luminar’s own colours</span></button>`+(wares?'<button class="gm-item" data-act="wares"><span>⚒ See his wares</span></button>':'');
      UI.sheet({title:'⚒ '+(keeper||'The smith')+' — your shield',html:h,act:a=>{
        if(a.indexOf('c:')===0){ const [,k,c]=a.split(':'); pick[k]=c; msg=''; draw(); return; }
        if(a==='luminar'){ pick=Object.assign({},DEF); msg=''; draw(); return; }
        if(a==='wares'){ UI.close(); wares(); return; }
        if(a==='paint'){ if((S.gold||0)<COST){ msg='“Thirty gold for the paint and the gilding, knight. Come back when your purse is heavier.”'; draw(); return; }
          if(GAME.addGold) GAME.addGold(-COST); else S.gold-=COST; S.shieldCol=Object.assign({},pick); Object.assign(cur,pick); GAME.save&&GAME.save(); GAME.changed&&GAME.changed();
          msg='“There. Let it dry a moment — the gold takes longest. Wear it well.”'; draw(); } }}); };
    draw(); }
  return {shield, preview, smithy, TINCT, DEF, ready:cb=>{ if(mask) cb(); else wait.push(cb); }};
})();
